package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addHours_TriageGen1Test {

    @Test
    public void testAddHours_Positive() {
        // Initialize at a specific time: 2023-01-01T10:00:00.000Z
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        int hoursToAdd = 5;

        dt.addHours(hoursToAdd);

        assertEquals(15, dt.getHourOfDay());
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddHours_Negative() {
        // Initialize at a specific time: 2023-01-01T10:00:00.000Z
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        int hoursToAdd = -5;

        dt.addHours(hoursToAdd);

        assertEquals(5, dt.getHourOfDay());
    }

    @Test
    public void testAddHours_Zero() {
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        dt.addHours(0);

        assertEquals(10, dt.getHourOfDay());
    }

    @Test
    public void testAddHours_CrossDayBoundary() {
        // 2023-01-01 23:00 -> add 2 hours -> 2023-01-02 01:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 23, 0, 0, 0);
        dt.addHours(2);

        assertEquals(1, dt.getHourOfDay());
        assertEquals(2, dt.getDayOfMonth());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(2023, dt.getYear());
    }

    @Test
    public void testAddHours_CrossMonthBoundary() {
        // 2023-01-31 23:00 -> add 2 hours -> 2023-02-01 01:00
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 23, 0, 0, 0);
        dt.addHours(2);

        assertEquals(1, dt.getHourOfDay());
        assertEquals(1, dt.getDayOfMonth());
        assertEquals(2, dt.getMonthOfYear());
    }

    @Test
    public void testAddHours_CrossYearBoundary() {
        // 2022-12-31 23:00 -> add 2 hours -> 2023-01-01 01:00
        MutableDateTime dt = new MutableDateTime(2022, 12, 31, 23, 0, 0, 0);
        dt.addHours(2);

        assertEquals(1, dt.getHourOfDay());
        assertEquals(1, dt.getDayOfMonth());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(2023, dt.getYear());
    }

    @Test
    public void testAddHours_LargeValue() {
        // Add many hours to ensure it handles large increments
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        int hoursToAdd = 24 * 365; // Exactly one year (non-leap)

        dt.addHours(hoursToAdd);

        assertEquals(2024, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddHours_LeapYear() {
        // 2024 is a leap year. Feb 28 23:00 + 2 hours -> Feb 29 01:00
        MutableDateTime dt = new MutableDateTime(2024, 2, 28, 23, 0, 0, 0);
        dt.addHours(2);

        assertEquals(1, dt.getHourOfDay());
        assertEquals(29, dt.getDayOfMonth());
        assertEquals(2, dt.getMonthOfYear());
    }
}
